from gen import *
c=Controller();s=c.s;R0=np.array([[0,1,0],[0,0,-1],[-1,0,0]])
for angle in [30,45]:
 R=Rot.from_euler('x',angle,degrees=True).as_matrix()@R0
 for yc in [.02,.04,.06]:
  for zc in [-.01,-.03]:
   for ti,th in enumerate([(1.24,-.2,.58,-.15,1.7),(1.05,-.24,1.17,-.06,1.17)]):
    s.reset();c.q=rcb_dtb.INIT_Q.copy();s.record_start();c.hold(70);ob=c.d.xpos[s._obj].copy();p=ob-R@np.array([.075,0,.125])+[0,yc,zc]
    c.move(p+[0,0,.12],R,hand(0,th),150);c.move(p,R,n=120);c.hold(30);c.move(p,R,hand(1.3,th),120);c.hold(30);before=c.d.xpos[s._obj].copy();c.move(p+[0,0,.15],R,n=150);c.hold(60)
    after=c.d.xpos[s._obj].copy();lift=after[2]-before[2];print([angle,yc,zc,ti,lift,after.tolist()],flush=True);A=s.record_stop()
    if lift>.07:
     tag=f't2_{angle}_{yc}_{zc}_{ti}';s.save_trajectory(A,'/app/output/'+tag+'.npz');c.report(tag)
