from gen_v1 import *
c=Controller();s=c.s;s.record_start()
for q in np.load('/app/output/g2_0.075_0.npz')['actions']:c.step(q)
for i in range(500):
 gi=s.goal_index;g=s.goals[gi];rg=Rot.from_quat(g[3:]).as_matrix();op=c.d.xpos[s._obj].copy();ro=c.d.xmat[s._obj].reshape(3,3);pp,rp=c.pose();e=Rot.from_matrix(rg@ro.T).as_rotvec();tp=g[:3]+rg@ro.T@(pp-op);tr=rg@ro.T@rp
 q=c.ik(tp,tr);dq=q[:7]-c.q[:7];q=c.q.copy();q[:7]+=dq*min(1,.006/(abs(dq).max()+1e-10));c.step(q)
 if i%25==0 or s.goal_index!=gi:print(i,gi,'dist',s.goal_distance(gi),'ep',np.round(np.array(g[:3])-op,3),'er local',np.round(rg.T@e,3),'relpos',np.round(rp.T@(op-pp),3),'q',np.round(q[:7],2),flush=True)
 if s.goal_index!=gi:s.save_trajectory(np.array(s._recording),'/app/output/reach_'+str(s.goal_index)+'.npz')
c.report('final');c.snap('debug_servo');s.save_trajectory(s.record_stop(),'/app/output/debug_servo.npz')
PY
